(()=>{const t=document.getElementById('toast');document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',()=>{const s=b.dataset.copy;const done=()=>{if(!t)return;t.textContent='微信号已复制';t.classList.add('show');clearTimeout(t._h);t._h=setTimeout(()=>t.classList.remove('show'),1800)};const fb=()=>{const a=document.createElement('textarea');a.value=s;document.body.appendChild(a);a.select();try{document.execCommand('copy')}catch(e){}a.remove();done()};if(navigator.clipboard&&isSecureContext)navigator.clipboard.writeText(s).then(done,fb);else fb()}))})();
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;(()=>{if(reduce)return;const ks=[...document.querySelectorAll('[data-k]')],band=document.querySelector('.band');let r=0;
function up(){r=0;const h=innerHeight;ks.forEach(k=>{const b=k.getBoundingClientRect();const p=Math.max(0,Math.min(1,(h-b.top)/(h*.7)));k.style.setProperty('--p',p.toFixed(3))});const bb=band.getBoundingClientRect();band.style.setProperty('--sp',Math.max(0,Math.min(1,(h-bb.top)/(h+bb.height))).toFixed(3))}
addEventListener('scroll',()=>{if(!r)r=requestAnimationFrame(up)},{passive:true});up();
const sw=[...document.querySelectorAll('.sw')];let i=0;setInterval(()=>{if(document.hidden)return;sw.forEach((s,k)=>s.classList.toggle('on',k===i));i=(i+1)%sw.length},1400);})();